int splitCsv(const char* line, char* out) {
    int count = 0, w = 0;
    bool quoted = false;
    for (int i = 0; line[i] != '\0'; i++) {
        char ch = line[i];
        if (quoted) {
            if (ch == '"') {
                if (line[i + 1] == '"') {
                    out[w++] = '"';
                    i++;
                } else {
                    quoted = false;
                }
            } else {
                out[w++] = ch;
            }
        } else if (ch == '"') {
            quoted = true;
        } else if (ch == ',') {
            out[w++] = '\0';
            count++;
        } else {
            out[w++] = ch;
        }
    }
    out[w] = '\0';
    return count + 1;
}

