def add_commas(n):
    digits = str(abs(n))
    out = []
    for i, ch in enumerate(digits):
        if i > 0 and (len(digits) - i) % 3 == 0:
            out.append(",")
        out.append(ch)
    return ("-" if n < 0 else "") + "".join(out)

