static String addCommas(long n) {
    String digits = Long.toString(Math.abs(n));
    StringBuilder out = new StringBuilder();
    for (int i = 0; i < digits.length(); i++) {
        if (i > 0 && (digits.length() - i) % 3 == 0)
            out.append(',');
        out.append(digits.charAt(i));
    }
    return (n < 0 ? "-" : "") + out;
}

