void addCommas(long long n, char* out) {
    char digits[24];
    unsigned long long mag = n < 0 ? 0ULL - (unsigned long long)n : (unsigned long long)n;
    sprintf(digits, "%llu", mag);
    int len = strlen(digits), w = 0;
    if (n < 0) out[w++] = '-';
    for (int i = 0; i < len; i++) {
        if (i > 0 && (len - i) % 3 == 0)
            out[w++] = ',';
        out[w++] = digits[i];
    }
    out[w] = '\0';
}
